  document.body.appendChild(m);const close=()=>m.remove(),work=m.querySelector("#certificate-sign-work");m.querySelector(".modal-close").onclick=close;m.querySelector(".modal-cancel").onclick=close;
  const save=async(method,blob=null,mime=null,btn=null,savedId=null)=>{if(btn)buttonLoading(btn,true,"กำลังบันทึก...");let path=null;try{
    assertSignatureMethod(method);
    if(blob){const ext=mime==="image/png"?"png":mime==="image/webp"?"webp":"jpg";path=`certificate-signatures/${requestId}/${slot}/${crypto.randomUUID()}.${ext}`;const up=await supabase.storage.from("academic-registration").upload(path,blob,{contentType:mime});if(up.error)throw up.error;}
    const sg=await supabase.rpc("review_academic_registration_signed",{p_system_code:"academic_certificate",p_request_id:requestId,p_slot:slot,p_decision:m.querySelector('[name="decision"]').value,p_reason:m.querySelector('[name="reason"]').value||null,p_method:method,p_storage_path:path,p_signature_id:savedId});if(sg.error)throw sg.error;
    if(sig?.storage_path&&sig.bucket==="academic-registration"&&sig.storage_path!==path)await supabase.storage.from(sig.bucket||"academic-registration").remove([sig.storage_path]);
    close();toast("บันทึกส่วนตรวจแล้ว",academicCertificateSlotLabel(slot),"success");await loadAcademicRegistrationWorkspace();await renderDashboard();requestAnimationFrame(()=>location.hash=`academic-certificate-detail-${requestId}`);
  }catch(err){if(path)await supabase.storage.from("academic-registration").remove([path]);toast("บันทึกไม่สำเร็จ",err.message||String(err),"error");}finally{if(btn)buttonLoading(btn,false);}};
  m.querySelectorAll("[data-cert-sign]").forEach(b=>b.onclick=()=>{const method=b.dataset.certSign;if(method==="stored"){academicRegistrationSavedSignaturePicker(work,(signatureId,button)=>save("stored",null,null,button,signatureId));}else if(method==="paper"){work.innerHTML=`<button class="btn btn-primary" id="cert-paper">บันทึกความเห็นและเลือกเซ็นบนกระดาษ</button>`;work.querySelector("#cert-paper").onclick=e=>save("paper",null,null,e.target);}else if(method==="drawn"){work.innerHTML=`<div class="signature-canvas-wrap"><canvas id="signature-canvas" width="900" height="300"></canvas></div><div class="signature-canvas-actions"><button class="btn btn-ghost" id="signature-clear">ล้าง</button><button class="btn btn-primary" id="cert-drawn">บันทึก</button></div>`;setupSignatureCanvas(m);work.querySelector("#cert-drawn").onclick=async e=>{if(!m._signatureHasInk?.())return toast("ยังไม่มีลายเซ็น","","error");await save("drawn",await canvasBlob(work.querySelector("#signature-canvas")),"image/png",e.target);};}else{work.innerHTML=`<div class="field"><label>ไฟล์ลายเซ็น</label><input class="input" id="cert-sign-file" type="file" accept="image/png,image/jpeg,image/webp"></div><button class="btn btn-primary" id="cert-upload">บันทึก</button>`;work.querySelector("#cert-upload").onclick=async e=>{const f=work.querySelector("#cert-sign-file").files[0];if(!f)return toast("กรุณาเลือกไฟล์","","error");await save("upload",f,f.type,e.target);};}});
